def die(msg: str) -> None:
    print()
    print("ERROR:", msg, file=sys.stderr)
    raise SystemExit(1)

def hb(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def hf(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for block in iter(lambda: f.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()

def need(label: str, data: bytes, markers) -> None:
    text = data.decode("utf-8", errors="replace")
    missing = [m for m in markers if m not in text]
    if missing:
        die(label + " missing marker(s):\n  - " + "\n  - ".join(missing))

def patch_render(data: bytes) -> bytes:
    if hb(data) != B3["src/GameSrc/render.c"]:
        die("B3 render input hash mismatch.")

    text = data.decode("utf-8")

    if text.count(DECL_ANCHOR) != 1:
        die("render.c declaration anchor mismatch.")

    text = text.replace(DECL_ANCHOR, DECL_ANCHOR + DECL_ADD, 1)

    start = text.find(REGION_START)
    end0 = text.find(REGION_END, start)
    if start < 0 or end0 < 0:
        die("B3 stereo region not found.")

    end = end0 + len(REGION_END)
    old = text[start:end]

    if old.count("fr_rend(NULL);") < 3:
        die("B3 fr_rend census mismatch.")

    output = (text[:start] + NEW_REGION + text[end:]).encode("utf-8")
    out_text = output.decode("utf-8")
    marker = out_text.find("PROJECT CITADEL C3D R3D7A AVP STEREO PARITY1")
    ending = out_text.find("citadel_3ds_stereo_end_frame();", marker)
    block = out_text[marker:ending]

    if block.count("fr_rend(NULL);") != 2:
        die("R3D7A scheduler does not contain exactly stereo+mono fr_rend.")

    if "citadel_3ds_stereo_begin_right_pass();" in block:
        die("R3D7A scheduler unexpectedly contains a right engine pass.")

    return output

def find_base_render() -> Path:
    candidates = sorted(
        CPROOT.glob("CITADEL_C3D_R3D7A_PRE_AVP_PARITY_*"),
        key=lambda p: p.stat().st_mtime,
        reverse=True,
    )
    for cp in candidates:
        p = cp / "delta/src/GameSrc/render.c"
        if p.is_file() and hf(p) == B3["src/GameSrc/render.c"]:
            return p

    die("Exact pre-A1 B3 render checkpoint not found.")

def desired_a1_render() -> bytes:
    return patch_render(find_base_render().read_bytes())

