    if B_STAGE.is_file():
        candidates.append(B_STAGE)

    for p in Path("/c/Projects").glob("*R3D7B*DEPTH*WARP*.3dsx"):
        if p.is_file() and p not in candidates:
            candidates.append(p)

    valid = []
    for p in candidates:
        data = p.read_bytes()
        if all(marker in data for marker in B_BINARY_MARKERS):
            valid.append(p)

    if not valid:
        die("Verified staged R3D7B hardware-tested binary was not found.")

    valid.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    return valid[0]

