def decode_c() -> bytes:
    data = gzip.decompress(base64.b64decode(C_PAYLOAD))
    if hb(data) != C_SHOCK:
        die("Embedded R3D7C Shock.c hash mismatch.")

    need(
        "R3D7C Shock.c",
        data,
        (
            "PROJECT CITADEL C3D R3D7C CMDBUF512 SHIPRC1 ACTIVE",
            "CITADEL-C3D-R3D7C-CMDBUF512-SHIPRC1",
            "CITADEL_R3D7C_CMDBUF_SIZE 0x80000u",
            "C3D_Init(CITADEL_R3D7C_CMDBUF_SIZE)",
            "C3D_GetCmdBufUsage()",
            "Command-buffer peak usage:",
            "R3D7C ship-candidate renderer path proven",
            "V2.0.0_SHIP_CANDIDATE_HARDENING",
            "RIGHT_ONLY_RECIPROCAL_W_DEPTH_WARP",
        ),
    )
    return data

def install_c(data: bytes) -> None:
    path = ROOT / "src/MacSrc/Shock.c"
    temp = path.with_name(path.name + ".r3d7c.tmp")
    temp.write_bytes(data)
    temp.replace(path)

    if hf(path) != C_SHOCK:
        die("Post-write R3D7C Shock.c verification failed.")

    print()
    print("PASS: R3D7C ship-RC one-file delta installed.")
    print("Shock.c SHA-256:", C_SHOCK)

def run(cmd: list[str], env: dict[str, str]) -> None:
    print()
    print("+", " ".join(cmd))
    subprocess.run(cmd, cwd=ROOT, env=env, check=True)

